CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,school TEXT,points INT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS squads(id SERIAL PRIMARY KEY,name TEXT NOT NULL,invite_code TEXT UNIQUE NOT NULL,owner_id INT REFERENCES users(id));
CREATE TABLE IF NOT EXISTS members(squad_id INT REFERENCES squads(id) ON DELETE CASCADE,user_id INT REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(squad_id,user_id));
CREATE TABLE IF NOT EXISTS checkins(squad_id INT REFERENCES squads(id) ON DELETE CASCADE,user_id INT REFERENCES users(id) ON DELETE CASCADE,day DATE NOT NULL,PRIMARY KEY(squad_id,user_id,day));
CREATE TABLE IF NOT EXISTS tasks(id SERIAL PRIMARY KEY,user_id INT REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,done BOOLEAN DEFAULT false,day DATE NOT NULL);
CREATE TABLE IF NOT EXISTS resources(id SERIAL PRIMARY KEY,user_id INT REFERENCES users(id),title TEXT NOT NULL,grade INT NOT NULL CHECK(grade BETWEEN 9 AND 12),subject TEXT NOT NULL,unit TEXT,kind TEXT NOT NULL,school TEXT,filename TEXT NOT NULL,original_name TEXT,downloads INT DEFAULT 0,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS posts(id SERIAL PRIMARY KEY,user_id INT REFERENCES users(id),subject TEXT NOT NULL,question TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS replies(id SERIAL PRIMARY KEY,post_id INT REFERENCES posts(id) ON DELETE CASCADE,user_id INT REFERENCES users(id),body TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS res_idx ON resources(grade,subject);
CREATE TABLE IF NOT EXISTS nudges(id SERIAL PRIMARY KEY,squad_id INT REFERENCES squads(id) ON DELETE CASCADE,from_id INT REFERENCES users(id) ON DELETE CASCADE,to_id INT REFERENCES users(id) ON DELETE CASCADE,seen BOOLEAN DEFAULT false,created_at TIMESTAMPTZ DEFAULT now());
